async function loadFiles(){const data=await api('platform/files/list');renderFiles(data.files||[]);return data}
function renderFiles(files=[]){$('filesList').innerHTML=files.length?files.map(f=>`<div class="list-item"><span>📦 <b>${escapeHtml(f.name)}</b><br><small>${fmtBytes(f.size)} · ${f.createdAt?new Date(f.createdAt).toLocaleString('id-ID'):''}</small></span><div class="actions"><button class="mini" data-file-download="${escapeHtml(f.path)}">UNDUH</button><button class="mini danger" data-file-delete="${escapeHtml(f.path)}">HAPUS</button></div></div>`).join(''):'<p>Belum ada file. Unggah ZIP pertamamu di atas.</p>'}
async function uploadZip(file){if(!file)return;if(!/\.zip$/i.test(file.name))return toast('Hanya file .zip yang diterima.',true);if(file.size>50*1024*1024)return toast('Ukuran maksimum 50 MB.',true);const status=$('zipUploadStatus'),wrap=$('zipProgressWrap'),bar=$('zipProgressBar'),txt=$('zipProgressText');status.classList.remove('hidden');status.textContent='Menyiapkan izin upload…';try{const sign=await post('platform/files/sign-upload',{filename:file.name,size:file.size});wrap.classList.remove('hidden');status.textContent='Mengunggah '+file.name+'…';await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('PUT',sign.signed_url);xhr.setRequestHeader('Content-Type','application/zip');xhr.setRequestHeader('x-upsert','false');xhr.upload.onprogress=e=>{if(e.lengthComputable){const pct=Math.round(e.loaded/e.total*100);bar.style.width=pct+'%';txt.textContent=pct+'% · '+fmtBytes(e.loaded)+' / '+fmtBytes(e.total)}};xhr.onload=()=>xhr.status>=200&&xhr.status<300?resolve():reject(new Error('Upload gagal (HTTP '+xhr.status+').'));xhr.onerror=()=>reject(new Error('Koneksi upload gagal.'));xhr.send(file)});bar.style.width='100%';txt.textContent='Selesai';status.textContent='✅ '+file.name+' berhasil diunggah.';toast('File ZIP terunggah.');await loadFiles()}catch(error){status.textContent='❌ '+error.message;toast(error.message,true)}finally{setTimeout(()=>{wrap.classList.add('hidden');bar.style.width='0%'},1500)}}
async function filesAction(event){const dl=event.target.closest('[data-file-download]'),del=event.target.closest('[data-file-delete]');if(dl){busy(dl,true,'MEMBUAT LINK…');try{const data=await post('platform/files/download',{path:dl.dataset.fileDownload});window.open(data.url,'_blank','noopener')}catch(error){toast(error.message,true)}finally{busy(dl,false)}}else if(del){if(!confirm('Hapus file ini secara permanen?'))return;busy(del,true);try{await post('platform/files/delete',{path:del.dataset.fileDelete});toast('File dihapus.');await loadFiles()}catch(error){toast(error.message,true)}finally{busy(del,false)}}}
async function loadShop(){const [shop,orders]=await Promise.all([api('wallet/shop'),api('wallet/orders')]);renderShop(shop,orders.orders||[]);return shop}
function renderShop(data={},orders=[]){const pkgs=Array.isArray(data.packages)?data.packages:[],prods=Array.isArray(data.products)?data.products:[];$('walletShopPackages').innerHTML=pkgs.length?pkgs.map(p=>`<div class="list-item"><span><b>${escapeHtml(p.name)}</b><br><small>${escapeHtml(p.description||'')} · RAM ${(p.memoryMb/1024).toFixed(p.memoryMb%1024?1:0)} GB · CPU ${escapeHtml(p.cpuPercent)}% · Disk ${(p.diskMb/1024).toFixed(p.diskMb%1024?1:0)} GB</small></span><div class="actions"><b>${formatIdr(p.price)}</b><button class="mini" data-buy-panel="${escapeHtml(p.id)}" ${data.panelReady?'':'disabled'}>BELI</button></div></div>`).join(''):`<p>${data.panelReady?'Belum ada paket panel yang dijual.':'Auto order panel belum diaktifkan owner.'}</p>`;$('walletShopProducts').innerHTML=prods.length?prods.map(p=>`<div class="list-item"><span><b>${escapeHtml(p.name)}</b><br><small>${escapeHtml(p.type==='premium'?('Premium '+escapeHtml(p.days)+' hari'):('Produk digital '+(p.inStock>0?('· stok '+escapeHtml(p.inStock)):'· stok habis')))} ${escapeHtml(p.description||'')}</small></span><div class="actions"><b>${formatIdr(p.price)}</b><button class="mini" data-buy-product="${escapeHtml(p.id)}" data-product-type="${escapeHtml(p.type)}">BELI</button></div></div>`).join(''):'<p>Belum ada produk yang dijual.</p>';renderOrders(orders)}
function renderOrders(orders=[]){$('walletOrders').innerHTML=orders.length?orders.map(o=>{let extra='';if(o.kind==='panel'&&o.panel)extra=`Server: ${escapeHtml(o.panel.serverName||'—')}<br>Panel: <a href="${escapeHtml(safeHttpsHref(o.panel.url||''))}" target="_blank" rel="noopener">${escapeHtml(o.panel.url||'')}</a><br>Username: <b>${escapeHtml(o.panel.username||'')}</b>${o.password?`<br>Password: <b>${escapeHtml(o.password)}</b>`:''}`;if(o.kind==='premium'&&o.premium)extra=`Premium untuk ${escapeHtml(o.premium.whatsapp||'')} sampai ${o.premium.premiumUntil?new Date(o.premium.premiumUntil).toLocaleString('id-ID'):'—'}`;if(o.kind==='digital')extra=o.delivery?`Produk terkirim:<br><b>${escapeHtml(o.delivery)}</b>`:'Produk terkirim';return `<div class="list-item"><span><b>${escapeHtml(o.itemName||o.itemId)}</b> · ${formatIdr(o.amount)}<br><small>${escapeHtml(o.createdAt?new Date(o.createdAt).toLocaleString('id-ID'):'')} · ${escapeHtml(o.reference||'')}</small>${extra?`<br><small>${extra}</small>`:''}</span><span class="chip ${o.status==='active'?'user':''}">${escapeHtml(String(o.status||'').toUpperCase())}</span></div>`}).join(''):'<p>Belum ada order.</p>'}
async function shopAction(event){const bp=event.target.closest('[data-buy-panel]'),bd=event.target.closest('[data-buy-product]');if(!bp&&!bd)return;const button=bp||bd,price=button.closest('.list-item')?.querySelector('.actions b')?.textContent||'';let payload,path;if(bp){if(!confirm(`Beli paket ini seharga ${price}? Server panel akan dibuat otomatis.`))return;path='wallet/buy-panel';payload={package_id:bp.dataset.buyPanel}}else{path='wallet/buy-product';payload={product_id:bd.dataset.buyProduct};if(bd.dataset.productType==='premium'){const wa=prompt('Nomor WhatsApp yang akan diaktifkan premium (format 628xxxxxxxxxx):');if(!wa)return;payload.whatsapp=wa.trim()}}busy(button,true,'MEMPROSES…');try{await post(path,payload);toast('Order berhasil! Detailnya ada di ORDER SAYA.');await Promise.all([loadWallet(),loadShop()])}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function openWallet(){await loadWallet();clearInterval(state.walletTimer);state.walletTimer=setInterval(()=>loadWallet().catch(()=>{}),10000)} async function openTopupPage(){await loadWallet();clearInterval(state.walletTimer);state.walletTimer=setInterval(()=>loadWallet().catch(()=>{}),10000)} async function openShopPage(){await loadShop()}
const panelState={servers:[],current:null,tab:'console',dir:'/',ws:null,connected:false,editing:null}
async function panelApi(action,extra={},method='GET',body){const query=new URLSearchParams({action,...extra});return api('panel?'+query.toString(),method==='GET'?{}:{method,body:JSON.stringify(body||{})})}
function panelFmtBytes(value){const n=Number(value)||0;if(n>=1073741824)return (n/1073741824).toFixed(2)+' GB';if(n>=1048576)return (n/1048576).toFixed(1)+' MB';if(n>=1024)return (n/1024).toFixed(1)+' KB';return n+' B'}
function panelStateLabel(state){return state==='running'?'BERJALAN':state==='offline'?'MATI':state==='starting'?'MEMULAI':state==='stopping'?'BERHENTI':state==='installing'?'PEMASANGAN':'TIDAK DIKETAHUI'}
async function openPanelPage(){await loadPanelServers()}
async function loadPanelServers(){const box=$('panelServerList');try{const data=await panelApi('servers');panelState.servers=Array.isArray(data.servers)?data.servers:[];if(!panelState.servers.length){box.innerHTML='<p>Belum ada server panel aktif. Beli paket panel dulu di halaman <a href="#wallet">Saldo</a>.</p>';$('panelDetail').classList.add('hidden');return}box.innerHTML=panelState.servers.map(server=>`<div class="list-item"><span><b>${escapeHtml(server.name||server.serverName||'Server Panel')}</b><br><small>${escapeHtml(server.itemName||'Paket panel')} · ${escapeHtml(server.identifier)}<br>Dibuat ${escapeHtml(server.createdAt?new Date(server.createdAt).toLocaleString('id-ID'):'—')}</small></span><span><span class="chip ${server.state==='running'?'partner':'user'}">${panelStateLabel(server.state)}</span><br><button class="mini" type="button" data-open-server="${escapeHtml(server.identifier)}">KELOLA →</button></span></div>`).join('');box.querySelectorAll('[data-open-server]').forEach(button=>button.addEventListener('click',()=>selectPanelServer(button.dataset.openServer)))}catch(error){box.innerHTML=`<p>${escapeHtml(error.message)}</p>`}}
function selectPanelServer(identifier){panelState.current=panelState.servers.find(item=>item.identifier===identifier)||null;if(!panelState.current)return;$('panelDetail').classList.remove('hidden');$('panelServerName').textContent=panelState.current.name||panelState.current.serverName||'SERVER';$('panelOpenOriginal').href=`${panelState.current.panelUrl}/server/${identifier}`;panelState.dir='/';panelSwitchTab('console');refreshPanelResources();$('panelDetail').scrollIntoView({behavior:'smooth',block:'start'})}
function panelSwitchTab(tab){panelState.tab=tab;document.querySelectorAll('[data-ptab]').forEach(button=>button.classList.toggle('active',button.dataset.ptab===tab));$('panelTabConsole').classList.toggle('hidden',tab!=='console');$('panelTabFiles').classList.toggle('hidden',tab!=='files');$('panelTabStartup').classList.toggle('hidden',tab!=='startup');if(tab==='console')connectPanelConsole();if(tab==='files')loadPanelFiles();if(tab==='startup')loadPanelStartup()}
async function refreshPanelResources(){const id=panelState.current?.identifier;if(!id)return;try{const data=await panelApi('resources',{server:id});const r=data.resources||{};const state=data.state||'unknown';const pill=$('panelState');pill.textContent=panelStateLabel(state);const server=panelState.current;const limits=server.limits||{};const memoryLimit=limits.memory?panelFmtBytes(limits.memory*1048576):'∞';const diskLimit=limits.disk?panelFmtBytes(limits.disk*1048576):'∞';$('panelUsage').textContent=`Status server: ${panelStateLabel(state)} · CPU ${Number(r.cpu_absolute||0).toFixed(1)}% · RAM ${panelFmtBytes(r.memory_bytes)} / ${memoryLimit} · Disk ${panelFmtBytes(r.disk_bytes)} / ${diskLimit}`}catch{$('panelUsage').textContent='Penggunaan: server belum siap dibaca (mungkin masih pemasangan).'}}
function panelConsoleWrite(text){const log=$('panelConsoleLog');if(!log)return;log.textContent+=String(text??'');if(log.textContent.length>60000)log.textContent=log.textContent.slice(-60000);log.scrollTop=log.scrollHeight}
function panelConsoleClear(message){const log=$('panelConsoleLog');if(log)log.textContent=message||''}
async function connectPanelConsole(){const id=panelState.current?.identifier;if(!id)return;if(panelState.ws){try{panelState.ws.close()}catch{}panelState.ws=null}panelConsoleClear('Menghubungkan konsol…\n');try{const ticket=await panelApi('websocket',{server:id});if(!ticket.socket||!ticket.token)throw new Error('Tiket konsol kosong.');const ws=new WebSocket(ticket.socket);panelState.ws=ws;ws.onopen=()=>{ws.send(JSON.stringify({event:'auth',args:[ticket.token]}))};ws.onmessage=async event=>{let payload;try{payload=JSON.parse(event.data)}catch{return}const name=payload.event;const arg=Array.isArray(payload.args)?payload.args[0]:'';if(name==='auth success'){panelState.connected=true;panelConsoleWrite('[Konsol terhubung]\n');refreshPanelResources()}else if(name==='console output'||name==='install output'){panelConsoleWrite(String(arg||'')+'\n')}else if(name==='status'){panelConsoleWrite(`[Status: ${panelStateLabel(String(arg||''))}]\n`);refreshPanelResources()}else if(name==='token expiring'||name==='token expired'){try{const fresh=await panelApi('websocket',{server:id});if(panelState.ws===ws)ws.send(JSON.stringify({event:'auth',args:[fresh.token]}))}catch{}}};ws.onclose=()=>{if(panelState.ws===ws){panelState.connected=false;panelConsoleWrite('[Konsol terputus]\n')}};ws.onerror=()=>{panelConsoleWrite('[Konsol gagal tersambung — tekan tab Konsol lagi untuk mencoba ulang]\n')}}catch(error){panelConsoleWrite('[Gagal: '+error.message+']\n')}}
async function panelPower(signal,button){const id=panelState.current?.identifier;if(!id)return;busy(button,true);try{await panelApi('power',{server:id},'POST',{signal});toast(`Perintah ${signal} terkirim.`);panelConsoleWrite(`[Power: ${signal}]\n`);setTimeout(refreshPanelResources,1500);setTimeout(refreshPanelResources,4500)}catch(error){toast(error.message,true)}finally{busy(button,false)}}
function panelJoin(dir,name){return (dir==='/'?'':dir)+'/'+name}
async function loadPanelFiles(){const id=panelState.current?.identifier;if(!id)return;const box=$('panelFileList');$('panelDirPath').textContent=panelState.dir;$('panelEditor').classList.add('hidden');try{const data=await panelApi('files_list',{server:id,directory:panelState.dir});panelState.files=Array.isArray(data.files)?data.files:[];const rows=[...panelState.files].sort((a,b)=>(a.isFile===b.isFile?a.name.localeCompare(b.name):a.isFile?1:-1));box.innerHTML=rows.map(file=>`<div class="list-item"><span><b>${file.isFile?'📄':'📁'} ${escapeHtml(file.name)}</b><br><small>${file.isFile?panelFmtBytes(file.size):'Folder'}${file.modifiedAt?' · '+escapeHtml(new Date(file.modifiedAt).toLocaleString('id-ID')):''}</small></span><span class="panel-file-actions">${file.isFile?`<button class="mini" type="button" data-fedit="${escapeHtml(file.name)}">EDIT</button><button class="mini" type="button" data-fdown="${escapeHtml(file.name)}">UNDUH</button>`:`<button class="mini" type="button" data-fopen="${escapeHtml(file.name)}">BUKA</button>`}${!file.isFile||/\.(zip|tar|tar\.gz|tgz)$/i.test(file.name)?`<button class="mini" type="button" data-fextract="${escapeHtml(file.name)}">EKSTRAK</button>`:''}<button class="mini" type="button" data-frename="${escapeHtml(file.name)}">NAMA</button><button class="mini" type="button" data-fdelete="${escapeHtml(file.name)}">HAPUS</button></span></div>`).join('')||'<p>Folder ini kosong.</p>';box.querySelectorAll('[data-fopen]').forEach(b=>b.addEventListener('click',()=>{panelState.dir=panelJoin(panelState.dir,b.dataset.fopen);loadPanelFiles()}));box.querySelectorAll('[data-fedit]').forEach(b=>b.addEventListener('click',()=>openPanelEditor(b.dataset.fedit)));box.querySelectorAll('[data-fdown]').forEach(b=>b.addEventListener('click',()=>downloadPanelFile(b.dataset.fdown)));box.querySelectorAll('[data-fextract]').forEach(b=>b.addEventListener('click',()=>extractPanelFile(b.dataset.fextract)));box.querySelectorAll('[data-frename]').forEach(b=>b.addEventListener('click',()=>renamePanelFile(b.dataset.frename)));box.querySelectorAll('[data-fdelete]').forEach(b=>b.addEventListener('click',()=>deletePanelFile(b.dataset.fdelete)))}catch(error){box.innerHTML=`<p>${escapeHtml(error.message)}</p>`}}
async function openPanelEditor(name){const id=panelState.current?.identifier;const file=panelJoin(panelState.dir,name);try{const data=await panelApi('files_contents',{server:id,file});panelState.editing=data.file;$('panelEditorName').textContent=data.file;$('panelEditorText').value=data.content;$('panelEditor').classList.remove('hidden');$('panelEditor').scrollIntoView({behavior:'smooth'})}catch(error){toast(error.message,true)}}
async function savePanelEditor(button){if(!panelState.editing)return;const id=panelState.current.identifier;busy(button,true);try{await panelApi('files_save',{server:id},'POST',{file:panelState.editing,content:$('panelEditorText').value});toast('File tersimpan.');loadPanelFiles()}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function downloadPanelFile(name){const id=panelState.current.identifier;try{const data=await panelApi('files_download',{server:id,file:panelJoin(panelState.dir,name)});if(data.url)window.open(data.url,'_blank','noopener');else toast('URL unduhan kosong.',true)}catch(error){toast(error.message,true)}}
async function extractPanelFile(name){const id=panelState.current.identifier;try{await panelApi('files_decompress',{server:id},'POST',{root:panelState.dir,file:name});toast('Arsip diekstrak.');loadPanelFiles()}catch(error){toast(error.message,true)}}
async function renamePanelFile(name){const to=prompt('Nama baru untuk '+name,name);if(!to||to===name)return;const id=panelState.current.identifier;try{await panelApi('files_rename',{server:id},'POST',{root:panelState.dir,from:name,to});toast('Nama diganti.');loadPanelFiles()}catch(error){toast(error.message,true)}}
async function deletePanelFile(name){if(!confirm('Hapus '+name+'? Tindakan ini tidak bisa dibatalkan.'))return;const id=panelState.current.identifier;try{await panelApi('files_delete',{server:id},'POST',{root:panelState.dir,files:[name]});toast('Terhapus.');loadPanelFiles()}catch(error){toast(error.message,true)}}
async function uploadPanelFile(fileInput){const file=fileInput.files?.[0];fileInput.value='';if(!file)return;const id=panelState.current.identifier;try{const data=await panelApi('files_upload_url',{server:id});if(!data.url)throw new Error('URL unggah kosong.');const form=new FormData();form.append('files',file);const response=await fetch(data.url,{method:'POST',body:form});if(!response.ok)throw new Error('Unggah gagal (HTTP '+response.status+').');toast('File terunggah.');loadPanelFiles()}catch(error){toast(error.message+' Unggah langsung mungkin dibatasi panel; alternatifnya buat file lewat tombol ＋ FILE.',true)}}
async function loadPanelStartup(){const id=panelState.current?.identifier;if(!id)return;const box=$('panelStartupVars');try{const data=await panelApi('startup',{server:id});$('panelStartupCommand').value=data.startupCommand||'';$('panelDockerImage').value=data.dockerImage||'';const vars=Array.isArray(data.variables)?data.variables:[];box.innerHTML=vars.map(v=>`<div class="list-item"><span><b>${escapeHtml(v.key)}</b><br><small>${escapeHtml(v.description||v.name||'')}</small></span><span class="panel-var-edit"><input type="text" value="${escapeHtml(v.value)}" data-var-input="${escapeHtml(v.key)}" ${v.editable?'':'disabled'}><button class="mini" type="button" data-var-save="${escapeHtml(v.key)}" ${v.editable?'':'disabled'}>SIMPAN</button></span></div>`).join('')||'<p>Tidak ada variable startup.</p>';box.querySelectorAll('[data-var-save]').forEach(b=>b.addEventListener('click',async()=>{const key=b.dataset.varSave;const input=box.querySelector(`[data-var-input="${key}"]`);busy(b,true);try{await panelApi('startup_variable',{server:id},'POST',{key,value:input.value});toast(`Variable ${key} disimpan. Restart server untuk menerapkan.`)}catch(error){toast(error.message,true)}finally{busy(b,false)}}))}catch(error){box.innerHTML=`<p>${escapeHtml(error.message)}</p>`}}
async function submitWalletTopup(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),amount=Number(form.elements.amount.value);if(!Number.isInteger(amount))return toast('Nominal top up tidak valid.',true);busy(button,true,'MEMBUAT INVOICE…');try{const result=await post('wallet/topup',{amount});toast(state.wallet?.mode==='manual_dana'?'Permintaan top up dikirim. Menunggu verifikasi owner.':'Invoice DANA dibuat. Selesaikan pembayaran untuk menambah saldo.');await loadWallet();$('walletActiveInvoice').scrollIntoView({behavior:'smooth',block:'center'})}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function sessionAction(event){const button=event.target.closest('[data-action]');if(!button)return;const id=button.dataset.id;if(button.dataset.action==='auto-ai'){await toggleSessionAutoAI(button,id);return}if(button.dataset.action==='new'){location.hash='connect';return}if(button.dataset.action==='settings'){state.selected=id;location.hash='settings';return}if(button.dataset.action==='restart'){busy(button,true);try{await post('session/restart',{session_id:id});toast('Restart dikirim.')}catch(error){toast(error.message,true)}finally{busy(button,false)}}if(button.dataset.action==='remove'&&confirm(`Hapus session +${id}?`)){busy(button,true);try{await post('session/logout',{session_id:id});toast('Session dihapus.');await loadSessions()}catch(error){toast(error.message,true)}finally{busy(button,false)}}}
async function requestPairing(event){event.preventDefault();const phone=$('pairPhone').value.replace(/\D/g,'');if(phone.length<8)return toast('Nomor WhatsApp tidak valid.',true);const button=event.currentTarget.querySelector('button');const copy=$('copyPairCode');$('pairCode').textContent='••••-••••';delete $('pairCode').dataset.code;copy.disabled=true;state.pairLogs=[];addPairLog('Meminta kode pairing dari server.');busy(button,true,'MEMINTA KODE...');try{const data=await post('session/pairing',{phone});const formatted=formatPairCode(data.code||data.pairingCode);$('pairCode').textContent=formatted.display;$('pairCode').dataset.code=formatted.code;copy.disabled=!formatted.code;$('pairStatus').textContent=data.message||'Kode dibuat. Masukkan di WhatsApp.';addPairLog(formatted.code?'Kode pairing diterima. Gunakan tombol Salin Code atau salin dari layar.':'Server belum mengirim kode pairing.');state.selected=phone;let lastStatus='';clearInterval(state.pairTimer);state.pairTimer=setInterval(async()=>{try{const status=await api(`session/status?session_id=${encodeURIComponent(phone)}`);const current=String(status.status||'pending');$('pairStatus').textContent=`Status: ${current}`;if(current!==lastStatus){lastStatus=current;addPairLog(`Status session: ${current}.`)}if(current==='connected'){clearInterval(state.pairTimer);addPairLog('WhatsApp berhasil terhubung.');toast('Bot berhasil terhubung.');location.hash='dashboard'}}catch{if(lastStatus!=='check_failed'){lastStatus='check_failed';addPairLog('Status session belum dapat diperiksa; mencoba lagi otomatis.')}}},4000)}catch(error){toast(error.message,true);$('pairStatus').textContent=error.message;addPairLog(`Pairing gagal: ${error.message||'kesalahan tidak diketahui'}.`)}finally{busy(button,false)}}
async function toggleSessionAutoAI(button,id){const enabled=button.dataset.enabled!=='1';busy(button,true,'MENYIMPAN...');try{const data=await post('settings/apply',{session_id:id,auto_ai:enabled});if(typeof data.settings?.auto_ai!=='boolean')throw Error('Status AutoAI belum terkonfirmasi. Muat ulang.');const item=state.sessions.find(x=>String(x.sessionId)===String(id));if(item)item.auto_ai=data.settings.auto_ai;renderSessions();if(state.settingsFor===String(id)&&state.selected===String(id))$('settingsForm').elements.auto_ai.checked=data.settings.auto_ai;toast(`AutoAI session +${id} ${data.settings.auto_ai?'ON':'OFF'}.`)}catch(error){toast(error.message,true)}finally{busy(button,false)}}
let settingsLoadVersion=0;
async function openSettings(){await loadSessions();if(!state.sessions.length){location.hash='connect';return}sessionOptions($('settingsSession'));if(!state.selected||!state.sessions.some(item=>String(item.sessionId)===String(state.selected)))state.selected=String(state.sessions[0].sessionId);$('settingsSession').value=state.selected;await loadSettings()}
