function renderFeedback(rows=[]){const list=$('feedbackList');list.innerHTML=rows.map(row=>{const meta=row.metadata&&typeof row.metadata==='object'?row.metadata:{};const isBot=meta.source==='bot';const target=meta.target==='bot'?`BOT +${meta.session_id||'\u2014'}`:meta.target==='bot-main'?'BOT UTAMA':'WEBSITE';const targetChip=meta.target==='bot'?'partner':'user';const title=escapeHtml(meta.title||'Laporan bug');const description=escapeHtml(meta.description||'');const steps=meta.steps?`<div class="feedback-steps"><b>LANGKAH</b><br>${escapeHtml(meta.steps)}</div>`:'';const plugin=meta.plugin?`<div class="feedback-steps"><b>PLUGIN</b><br>${escapeHtml(meta.plugin)}${meta.command?` \u00b7 ${escapeHtml(meta.command)}`:''}${Number(meta.occurrences)>1?` \u00b7 terjadi ${Number(meta.occurrences)}\u00d7`:''}</div>`:'';const resolution=meta.resolution?`<div class="feedback-steps"><b>PERBAIKAN</b><br>${escapeHtml(meta.resolution)}${meta.resolved_at?` \u00b7 ${escapeHtml(new Date(meta.resolved_at).toLocaleString('id-ID'))}`:''}</div>`:'';const date=escapeHtml(new Date(row.created_at).toLocaleString('id-ID'));const status=String(meta.status||'open').toLowerCase();return`<article class="feedback-item ${status==='resolved'?'is-resolved':''}"><div class="feedback-meta"><span class="chip ${targetChip}">${target}</span><span class="chip ${status==='resolved'?'user':'owner'}">${escapeHtml(status.toUpperCase())}</span>${isBot?`<span class="chip">\u{1F916} OTOMATIS</span>`:''}<time>${date}</time></div><h4>${title}</h4><p>${description}</p>${plugin}${resolution}${steps}</article>`}).join('')||'<p>Belum ada laporan feedback.</p>'}async function loadFeedback(){const data=await api('platform/feedback');renderFeedback(data.feedback||[])}
