async function pluginAction(event){const button=event.target.closest('[data-plugin-copy],[data-plugin-download],[data-plugin-install],[data-plugin-delete]');if(!button)return;try{if(button.dataset.pluginCopy||button.dataset.pluginDownload){const id=button.dataset.pluginCopy||button.dataset.pluginDownload,item=(await api(`platform/plugins/${id}`)).plugin;if(button.dataset.pluginCopy){await navigator.clipboard.writeText(item.code);toast('Code disalin.')}else{const url=URL.createObjectURL(new Blob([item.code],{type:'text/javascript'})),link=document.createElement('a');link.href=url;link.download=item.filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}if(button.dataset.pluginInstall){const sessionId=$('pluginSession').value;if(!sessionId)throw new Error('Pilih session.');if(confirm(`Install plugin ke +${sessionId}?`)){await post(`platform/plugins/${button.dataset.pluginInstall}/install`,{session_id:sessionId});toast('Plugin terinstal.')}}if(button.dataset.pluginDelete&&confirm('Hapus plugin dari katalog?')){await api(`platform/plugins/${button.dataset.pluginDelete}`,{method:'DELETE'});await loadPlugins()}}catch(error){toast(error.message,true)}}
