function mainConnectionLabel(status={}){if(status.main_bot_enabled===false)return 'NONAKTIF';if(status.connected)return 'TERHUBUNG';if(status.pairing_active)return 'MENUNGGU PAIRING';if(status.registered)return 'TERDAFTAR / MENYAMBUNG';return 'BELUM TERPASANG'}
function renderMainPairCode(){const output=$('mainBotPairCode'),copy=$('copyMainBotPairCode');if(!output||!copy)return;const formatted=formatPairCode(state.mainPairCode);output.textContent=formatted.display;output.dataset.code=formatted.code;copy.disabled=!formatted.code}
function detectMainPairCode(){/* Status server adalah sumber utama kode pairing (Task78). Parser log hanya cadangan kalau endpoint status tidak bisa dibaca, supaya kode lama di log tidak menimpa kode baru/kedaluwarsa. */if(state.mainStatusHasServer)return;const source=state.mainConsoleOutput.slice(Math.max(0,state.mainPairingSearchOffset));const matches=[...source.matchAll(/PAIRING\s+CODE\s*:\s*([a-z0-9-]{4,40})/gi)];const value=matches.at(-1)?.[1]||'';if(!value)return;const formatted=formatPairCode(value);if(formatted.code){state.mainPairCode=formatted.code;renderMainPairCode();setPairingNote('Pairing code siap disalin.')}}
function renderMainConsole(){const box=$('mainConsoleLogs');if(!box)return;box.textContent=state.mainConsoleOutput||'Belum ada output console.';box.scrollTop=box.scrollHeight;detectMainPairCode()}
async function loadMainConsoleLogs(){if(!hasMainBotAccess())return;const data=await api(`platform/main-console/logs?cursor=${encodeURIComponent(state.mainConsoleCursor)}`);if(data.reset){state.mainConsoleOutput='';state.mainPairingSearchOffset=0}for(const chunk of Array.isArray(data.chunks)?data.chunks:[])state.mainConsoleOutput+=String(chunk?.text||'');if(state.mainConsoleOutput.length>700000){const excess=state.mainConsoleOutput.length-700000;state.mainConsoleOutput=state.mainConsoleOutput.slice(excess);state.mainPairingSearchOffset=Math.max(0,state.mainPairingSearchOffset-excess)}state.mainConsoleCursor=Math.max(state.mainConsoleCursor,Number(data.cursor)||0);renderMainConsole()}
async function loadMainConsole(options={}){if(!hasMainBotAccess())return;const boxes=[$('mainConsoleStatus'),$('mainSettingsStatus')].filter(Boolean);if(!options.quiet)boxes.forEach(box=>box.textContent='Memeriksa status bot utama…');const data=await api('platform/main-console/status');const status=data.status||{},ready=Boolean(status.console_prompt_active),enabled=Boolean(status.main_bot_enabled),pairButton=$('requestMainBotPairing'),numberInput=$('mainBotNumber');const html=`<b>${escapeHtml(mainConnectionLabel(status))}</b><br><small>Bot utama: ${escapeHtml(String(enabled?'AKTIF':'NONAKTIF'))} · Nomor: ${escapeHtml(status.pairing_number_masked||'belum diatur')} · Socket: ${escapeHtml(String(status.socket_ready?'siap':'belum siap'))} · Prompt console: ${escapeHtml(String(ready?'aktif':'tidak aktif'))} · Runtime: ${escapeHtml(String(status.uptime_seconds||0))} dtk</small>`;boxes.forEach(box=>box.innerHTML=html);applyMainBotToggle(status);applyAutoreadToggle(status);if(numberInput)numberInput.disabled=false;if(pairButton)pairButton.disabled=false;applyMainPairingStatus(status)}
