async function saveMainSettings(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]');busy(button,true,'MENYIMPAN...');try{const data=await post('platform/main-console/settings',mainSettingsPayload(form));state.mainSettings=data.settings||state.mainSettings;state.mainApiKeys=data.api_keys||state.mainApiKeys;renderMainSettings(data);toast('Setting bot utama tersimpan dan langsung berlaku.')}catch(error){toast(error.message,true)}finally{busy(button,false)}}
