async function saveMainApiKey(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]'),provider=form.elements.provider.value,key=form.elements.api_key.value.trim();if(key.length<16)return toast('Tempel API key yang valid (minimal 16 karakter).',true);busy(button,true,'MENYIMPAN...');try{const data=await post('platform/main-console/apikey',{provider,api_key:key});form.elements.api_key.value='';state.mainApiKeys=data.api_keys||state.mainApiKeys;renderMainApiKeyStatus(state.mainApiKeys);toast(`API key ${provider} tersimpan.`)}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function deleteMainApiKey(){const form=$('mainApiKeyForm');if(!form)return;const provider=form.elements.provider.value;if(provider==='openrouter')return toast('Key OpenRouter diganti dengan mengisi key baru, bukan dihapus.',true);if(!confirm(`Hapus API key ${provider}? Auto-AI akan memakai penyedia lain atau berhenti sampai key baru diisi.`))return;const button=$('deleteMainApiKey');busy(button,true,'MENGHAPUS...');try{const data=await post('platform/main-console/apikey',{provider,delete:true});state.mainApiKeys=data.api_keys||state.mainApiKeys;renderMainApiKeyStatus(state.mainApiKeys);toast(`API key ${provider} dihapus.`)}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function openMainSettings(){state.mainConsoleOutput='';await loadMainConsole();await loadMainSettings().catch(error=>toast(error.message,true));startMainStatusPolling()}
async function openMainPairing(){state.mainPairingSearchOffset=state.mainConsoleOutput.length;renderMainPairCode();const pairAgain=$('requestMainBotPairCode'),remaining=Math.max(0,Math.ceil(((state.pairCooldownUntil||0)-Date.now())/1000));if(pairAgain){pairAgain.disabled=remaining>0;pairAgain.textContent=remaining>0?`TUNGGU ${remaining} DETIK`:'MINTA CODE LAGI'}if(remaining>0)startPairCooldown(remaining);await loadMainConsole();await loadMainConsoleLogs().catch(()=>{});startMainStatusPolling()}
async function openMainConsole(){state.mainConsoleCursor=0;state.mainConsoleOutput='';state.mainPairingSearchOffset=0;renderMainPairCode();renderMainConsole();await loadMainConsole();await loadMainConsoleLogs();clearInterval(state.mainConsoleTimer);state.mainConsoleTimer=setInterval(()=>{loadMainConsoleLogs().catch(()=>{})},1500);startMainStatusPolling()}
async function submitMainConsoleInput(event){event.preventDefault();const form=event.currentTarget,input=$('mainConsoleInput').value,button=form.querySelector('button');if(!input)return;busy(button,true,'MENGIRIM...');try{await post('platform/main-console/input',{input});$('mainConsoleInput').value='';await loadMainConsoleLogs()}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function submitMainBotPairing(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');let number=$('mainBotNumber').value.replace(/\D/g,'');if(number.startsWith('0'))number=`62${number.slice(1)}`;else if(number.startsWith('8'))number=`62${number}`;if(number.length<8||number.length>15)return toast('Nomor bot utama tidak valid.',true);busy(button,true,'MENGIRIM...');state.mainPairCode='';state.mainPairingSearchOffset=state.mainConsoleOutput.length;renderMainPairCode();setPairingNote('Nomor disimpan di server bot. Menunggu pairing code…');try{const data=await post('platform/main-console/pairing-number',{number});$('mainBotNumber').value='';if(data?.status)applyMainPairingStatus({...data.status,pairing_code:data.pairing_code||data.status.pairing_code||''});startMainStatusPolling();startPairCooldown(60);await loadMainConsoleLogs().catch(()=>{})}catch(error){$('mainBotPairingStatus').textContent=error.message;toast(error.message,true)}finally{busy(button,false)}}
async function copyMainBotPairCode(){const code=$('mainBotPairCode')?.dataset.code||'';if(!code)return toast('Belum ada pairing code untuk disalin.',true);try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(code);else{const area=document.createElement('textarea');area.value=code;area.style.position='fixed';area.style.opacity='0';document.body.append(area);area.select();if(!document.execCommand('copy'))throw new Error('copy failed');area.remove()}setPairingNote('Pairing code disalin ke clipboard.');toast('Pairing code disalin.')}catch{toast('Tidak dapat menyalin otomatis. Salin dari layar.',true)}}
/* Task78: kode pairing dibaca dari status server (bukan hanya dari log console),
 * jadi selalu terlihat di halaman Bot Utama walau buffer log sudah berputar. */
function applyMainPairingStatus(status={}){state.mainStatusHasServer=true;const raw=String(status.pairing_code||'').replace(/[^a-z0-9]/gi,'').toUpperCase();const age=Number(status.pairing_code_age_seconds);/* kode pairing hidup ±60 detik; di atas 120 detik anggap kedaluwarsa supaya owner tidak memasukkan kode mati */const fresh=Boolean(raw)&&(!Number.isFinite(age)||age<=120);if(fresh)state.mainPairCode=raw;const output=$('mainBotPairCode'),copy=$('copyMainBotPairCode'),note=$('mainBotPairingStatus');if(raw&&fresh){const formatted=formatPairCode(raw);if(output){output.textContent=formatted.display;output.dataset.code=formatted.code}if(copy)copy.disabled=false}else{state.mainPairCode='';if(output){output.textContent='••••-••••';output.dataset.code=''}if(copy)copy.disabled=true}
if(!note)return;const info=status.pairing_number_set?`Nomor tersimpan: ${status.pairing_number_masked||'-'}.`:'Belum ada nomor tersimpan.';
if(status.pairing_error){const err=String(status.pairing_error);/* saran HAPUS SESI hanya relevan untuk masalah koneksi/sesi, bukan saat WhatsApp membatasi permintaan */const sessionHint=/rate|Tunggu|dibatasi/i.test(err)?'':" Kalau penyebabnya sesi rusak/logout, tekan HAPUS SESI BOT UTAMA lalu MINTA CODE LAGI.";note.textContent=`Pairing gagal: ${err}${sessionHint}`}
else if(status.pairing_pending){note.textContent='Meminta kode pairing ke WhatsApp… tunggu ±15 detik; halaman ini menyegarkan sendiri tiap 4 detik.'}
else if(raw&&fresh){note.textContent=`${info} Kode dibuat ${Number.isFinite(age)?`${age} detik lalu`:'baru saja'}. Buka WhatsApp → Perangkat tertaut → Tautkan dengan nomor telepon, lalu masukkan kode (hidup ±60 detik). Kalau kedaluwarsa, tekan MINTA CODE LAGI.`}
else if(raw&&!fresh){note.textContent=`${info} Kode terakhir (${raw.replace(/(.{4})(.{4})/,'$1-$2')}) sudah kedaluwarsa — dibuat ${Math.round(age/60)} menit lalu. Tekan MINTA CODE LAGI untuk kode baru.`}
else if(status.connected){note.textContent=`${info} Bot utama sudah tertaut dan terhubung.`}
else if(status.main_bot_enabled===false){note.textContent=`Bot utama NONAKTIF. ${info} API dan jadibot tetap jalan; pairing tidak diperlukan selama bot utama nonaktif.`}
else{note.textContent=`${info} Socket: ${status.socket_ready?'siap':'belum siap'} · terdaftar: ${status.registered?'ya':'belum'}. Tekan SIMPAN & MINTA CODE atau MINTA CODE LAGI untuk meminta kode pairing.`}}
async function refreshMainStatus(){if(!hasMainBotAccess()||state.mainStatusBusy)return;state.mainStatusBusy=true;try{await loadMainConsole({quiet:true})}catch{state.mainStatusHasServer=false}finally{state.mainStatusBusy=false}}
function startMainStatusPolling(){clearInterval(state.mainStatusTimer);state.mainStatusTimer=setInterval(()=>{refreshMainStatus()},4000)}
/* WhatsApp membatasi permintaan kode berulang (rate-overlimit). Tombol
 * dimatikan sementara 60 detik setelah setiap permintaan supaya tidak
 * menembak server berkali-kali. */
function startPairCooldown(seconds=60){clearInterval(state.pairCooldownTimer);let left=Math.max(0,Number(seconds)||0);state.pairCooldownUntil=Date.now()+left*1000;const button=$('requestMainBotPairCode');if(!button)return;const render=()=>{if(left>0){button.disabled=true;button.textContent=`TUNGGU ${left} DETIK`}else{button.disabled=false;button.textContent='MINTA CODE LAGI';state.pairCooldownUntil=0;clearInterval(state.pairCooldownTimer);state.pairCooldownTimer=null}};render();state.pairCooldownTimer=setInterval(()=>{left-=1;render()},1000)}
async function requestMainBotPairCode(){const button=$('requestMainBotPairCode');if(!button||!hasMainBotAccess())return;busy(button,true,'MEMINTA...');state.mainPairCode='';renderMainPairCode();setPairingNote('Meminta kode pairing ke WhatsApp… tunggu ±15 detik.');try{const data=await post('platform/main-console/pairing-request',{});if(data?.status)applyMainPairingStatus({...data.status,pairing_code:data.pairing_code||data.status.pairing_code});else if(data?.pairing_code)applyMainPairingStatus({pairing_code:data.pairing_code});startMainStatusPolling();await loadMainConsoleLogs().catch(()=>{});startPairCooldown(60);toast('Permintaan kode dikirim. Kode tampil di kotak PAIRING CODE.')}catch(error){setPairingNote('Gagal meminta kode: '+error.message);toast(error.message,true)}finally{busy(button,false)}}
async function deleteMainBotSession(){const button=$('deleteMainBotSession');if(!button||!hasMainBotAccess())return;if(!confirm('Hapus sesi WhatsApp bot utama? Bot harus pairing ulang. Sesi jadibot TIDAK ikut terhapus.'))return;busy(button,true,'MENGHAPUS...');try{state.mainPairCode='';renderMainPairCode();setPairingNote('Menghapus sesi bot utama…');const data=await post('platform/main-console/main-session',{});if(data?.status)applyMainPairingStatus({...data.status,pairing_code:data.pairing_code||data.status.pairing_code||''});startMainStatusPolling();await loadMainConsoleLogs().catch(()=>{});toast(`Sesi bot utama dihapus (${Number(data?.removed)||0} berkas).`) }catch(error){setPairingNote('Gagal menghapus sesi: '+error.message);toast(error.message,true)}finally{busy(button,false)}}
async function resetMainBotConfig(){const button=$('resetMainBotConfig');if(!button||!hasMainBotAccess())return;if(!confirm('Reset konfigurasi bot utama? Nomor pairing dihapus dan bot utama diaktifkan kembali. Kamu perlu memasukkan nomor baru.'))return;busy(button,true,'MERESET...');try{state.mainPairCode='';renderMainPairCode();setPairingNote('Mereset konfigurasi bot utama…');const data=await post('platform/main-console/main-config',{});if(data?.status)applyMainPairingStatus({...data.status,pairing_code:data.pairing_code||data.status.pairing_code||''});else await loadMainConsole({quiet:true});const numberField=$('mainBotNumber');if(numberField)numberField.value='';startMainStatusPolling();toast('Config bot utama direset: nomor dikosongkan, bot diaktifkan.')}catch(error){setPairingNote('Gagal mereset config: '+error.message);toast(error.message,true)}finally{busy(button,false)}}
function clearMainConsole(){state.mainConsoleOutput='';state.mainPairingSearchOffset=0;renderMainConsole()}
function roleSelect(user){return`<select multiple size="5" data-role-id="${escapeHtml(user.id)}" ${user.locked?'disabled':''}>${['user','admin','partner','owner','developer'].map(role=>`<option value="${role}" ${(user.roles||[]).includes(role)?'selected':''}>${role}</option>`).join('')}</select>`}
function ownerNumberStat(id,value,error){
  const node=$(id);if(!node)return;
  const missing = value===null || value===undefined || (typeof value==='number' && !Number.isFinite(value));
  node.textContent = missing ? '—' : String(value);
  node.classList.toggle('is-unknown',missing);
  node.title = error ? ('Tidak tersedia: '+error) : '';
}
function ownerLiveStatus(problems,stamp){
  const box=$('ownerLive'),status=$('ownerLiveStatus'),detail=$('ownerLiveErrors');
  if(!box||!status)return;
  const bad=problems.length>0;
  box.classList.toggle('bad',bad);
  const dot=box.querySelector('.dot');if(dot)dot.classList.toggle('bad',bad);
  status.textContent = bad ? ('Sebagian data tidak tersedia · '+stamp) : ('Live · diperbarui '+stamp);
  if(detail)detail.textContent = problems.join(' · ');
}
function ownerStamp(value){
  try{return new Date(value||Date.now()).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}
  catch{return '—'}
}
async function refreshOwnerStats(quiet){
  if(!hasRole('owner'))return null;
  try{
    const live=await api('platform/admin/live');
    ownerNumberStat('ownerUsers',live.users?live.users.value:null,live.users?live.users.error:null);
    ownerNumberStat('ownerOnline',live.sessions?live.sessions.online:null,live.sessions?live.sessions.error:null);
    ownerNumberStat('ownerSessions',live.sessions?live.sessions.total:null,live.sessions?live.sessions.error:null);
    const problems=[];
    if(live.users&&live.users.error&&(live.users.value===null||live.users.value===undefined))problems.push('akun: '+live.users.error);
    if(live.sessions&&live.sessions.error){
      const adaAngka=live.sessions.total!==null&&live.sessions.total!==undefined;
      problems.push('status bot: '+live.sessions.error+(adaAngka?' — angka diambil dari agregat /api/stats':''));
    }
    if(live.sessions&&live.sessions.source==='stats'&&!live.sessions.error)problems.push('sesi memakai agregat /api/stats');
    ownerLiveStatus(problems,ownerStamp(live.generatedAt));
    return live;
  }catch(error){
    ownerNumberStat('ownerUsers',null,error.message);
    ownerNumberStat('ownerOnline',null,error.message);
    ownerNumberStat('ownerSessions',null,error.message);
    ownerLiveStatus(['statistik: '+error.message],ownerStamp());
    if(!quiet)toast(error.message,true);
    return null;
  }
}
async function loadOwner(){
  if(!hasRole('owner'))return;
  /* Setiap sumber dimuat terpisah: kegagalan audit tidak boleh mengosongkan
     daftar akun, dan kegagalan daftar akun tidak boleh menyembunyikan audit. */
  const results=await Promise.allSettled([api('platform/admin/users'),api('platform/audit')]);
  const data=results[0].status==='fulfilled'?results[0].value:null;
  if(data){
    $('ownerTable').innerHTML=(data.users||[]).map(user=>`<tr data-search="${escapeHtml(`${user.username||''} ${user.email||''}`.toLowerCase())}"><td><b>${escapeHtml(user.username||'Tanpa username')}</b><br><span>${escapeHtml(user.email||'')}</span>${user.locked?'<br><span class="chip owner">LOCKED</span>':''}</td><td>${roleSelect(user)}</td><td>${(user.sessions||[]).map(session=>`<div>+${escapeHtml(session.sessionId)} ${escapeHtml(session.status)}</div>`).join('')||'—'}</td><td>${user.banned?'<span class="chip owner">BANNED</span>':'<span class="chip user">ACTIVE</span>'}</td><td>${user.locked?'—':`<div class="actions"><button class="mini" data-user-save="${escapeHtml(user.id)}">SAVE</button><button class="mini" data-user-ban="${escapeHtml(user.id)}" data-banned="${Boolean(user.banned)}">${user.banned?'UNBAN':'BAN'}</button><button class="mini danger" data-user-delete="${escapeHtml(user.id)}">HAPUS</button></div>`}</td></tr>`).join('');
    if(data.totals){
      const botError = data.errors ? data.errors.sessions : null;
      ownerNumberStat('ownerUsers',data.totals.users===undefined?null:data.totals.users,null);
      ownerNumberStat('ownerOnline',data.totals.online===undefined?null:data.totals.online,botError);
      ownerNumberStat('ownerSessions',data.totals.sessions===undefined?null:data.totals.sessions,botError);
    }
    filterOwner();
  }else{
    const message=results[0].reason&&results[0].reason.message?results[0].reason.message:'Kesalahan tidak diketahui.';
    $('ownerTable').innerHTML=`<tr><td colspan="5"><b>Daftar akun tidak dapat dimuat.</b><br><small>${escapeHtml(message)}</small></td></tr>`;
  }
  if(results[1].status==='fulfilled'){
    renderAudit(results[1].value.logs||[]);
  }else{
    const message=results[1].reason&&results[1].reason.message?results[1].reason.message:'Kesalahan tidak diketahui.';
    $('auditList').innerHTML=`<div class="list-item"><span><b>Audit log tidak dapat dimuat.</b><br><small>${escapeHtml(message)}</small></span></div>`;
  }
  await refreshOwnerStats(true);
  clearInterval(state.ownerTimer);
  state.ownerTimer=setInterval(()=>{if(currentRoute()==='owner')refreshOwnerStats(true)},10000);
  try{await loadPanelAutoOrder()}catch{/* panel auto order punya statusnya sendiri di kartu */}
}
function defaultPanelPackages(){return[{id:'starter-1',name:'Starter 1 GB',description:'Paket awal',price:0,memoryMb:1024,cpuPercent:40,diskMb:1024,enabled:false},{id:'starter-2',name:'Starter 2 GB',description:'Paket awal',price:0,memoryMb:2048,cpuPercent:70,diskMb:2048,enabled:false},{id:'starter-4',name:'Starter 4 GB',description:'Paket awal',price:0,memoryMb:4096,cpuPercent:120,diskMb:4096,enabled:false}]}
function panelPackageCard(item={}){const value=(key,fallback='')=>escapeHtml(item[key]??fallback);return`<article class="panel" data-panel-package><div class="section-head"><h4>PAKET</h4><button class="mini danger" type="button" data-panel-package-remove>HAPUS</button></div><div class="form-grid"><label>ID Paket<input data-panel-field="id" maxlength="40" required pattern="[a-z0-9-]+" value="${value('id')}"></label><label>Nama Paket<input data-panel-field="name" maxlength="80" required value="${value('name')}"></label><label>Harga (Rp)<input data-panel-field="price" type="number" min="0" max="100000000" step="1" required value="${value('price',0)}"></label><label>RAM (MB)<input data-panel-field="memoryMb" type="number" min="128" max="1048576" step="1" required value="${value('memoryMb',1024)}"></label><label>CPU (%)<input data-panel-field="cpuPercent" type="number" min="1" max="100000" step="1" required value="${value('cpuPercent',40)}"></label><label>Disk (MB)<input data-panel-field="diskMb" type="number" min="128" max="10485760" step="1" required value="${value('diskMb',1024)}"></label></div><label>Deskripsi<textarea data-panel-field="description" maxlength="240">${value('description')}</textarea></label><label><input data-panel-field="enabled" type="checkbox" ${item.enabled?'checked':''}> Aktifkan paket ini untuk checkout</label></article>`}
function renderPanelPackages(packages){const editor=$('panelPackageEditor');const values=Array.isArray(packages)&&packages.length?packages:defaultPanelPackages();editor.innerHTML=values.map(panelPackageCard).join('')}
function currentPanelPackages(){return[...$('panelPackageEditor').querySelectorAll('[data-panel-package]')].map(card=>{const field=name=>card.querySelector(`[data-panel-field="${name}"]`);return{id:field('id').value.trim().toLowerCase(),name:field('name').value.trim(),description:field('description').value.trim(),price:Number(field('price').value),memoryMb:Number(field('memoryMb').value),cpuPercent:Number(field('cpuPercent').value),diskMb:Number(field('diskMb').value),enabled:field('enabled').checked}})}
function panelStatusText(data){const p=data||{},panel=p.pltaConfigured?'PLTA siap':'PLTA belum diisi',bridge=p.pltcConfigured?'Bridge PLTC siap':'Bridge PLTC belum diisi',payment=p.payment?.configured?(p.payment?.mode==='manual_dana'?'DANA manual siap · verifikasi owner':'TriPay DANA siap'):(p.payment?.mode==='manual_dana'?'DANA manual belum siap':'TriPay DANA belum diisi'),checkout=p.checkoutReady?'Checkout dapat dilanjutkan ke tahap provisioning.':'Checkout belum aktif.';return`${panel} · ${bridge} · ${payment}. ${checkout}`}
async function loadPanelAutoOrder(){if(!hasRole('owner'))return;const status=$('panelAutoOrderStatus');status.textContent='Memeriksa konfigurasi Panel Auto Order…';try{const data=await api('platform/panel/status');state.panelAutoOrder=data;status.textContent=panelStatusText(data);$('panelAutoOrderForm').elements.panel_url.value=data.panelUrl||'';$('panelAutoOrderForm').elements.site_url.value=data.siteUrl||location.origin;$('panelAutoOrderForm').elements.payment_mode.value=data.payment?.mode||'manual_dana';$('panelAutoOrderForm').elements.tripay_channel.value=data.payment?.channel||'DANA';$('panelAutoOrderForm').elements.clear_plta.checked=false;$('panelAutoOrderForm').elements.clear_pltc.checked=false;$('panelAutoOrderForm').elements.clear_tripay.checked=false;{const f=$('panelAutoOrderForm').elements;if(f.egg_id)f.egg_id.value=data.provisioning?.eggId||'';if(f.location_id)f.location_id.value=data.provisioning?.locationId||'';if(f.docker_image)f.docker_image.value=data.provisioning?.dockerImage||'';if(f.startup)f.startup.value=data.provisioning?.startup||''}renderPanelPackages(data.packages);renderPanelProductsSummary(data.products)}catch(error){status.textContent=`Konfigurasi Panel belum dapat dimuat: ${error.message}`;renderPanelPackages(state.panelAutoOrder?.packages)}await loadManualTopups().catch(error=>{$('manualTopupRequests').textContent=`Permintaan top up belum dapat dimuat: ${error.message}`})}
async function savePanelAutoOrder(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type="submit"]'),payload={panelUrl:form.elements.panel_url.value.trim(),siteUrl:form.elements.site_url.value.trim(),paymentMode:form.elements.payment_mode.value,tripayChannel:form.elements.tripay_channel.value.trim().toUpperCase(),clearPlta:form.elements.clear_plta.checked,clearPltc:form.elements.clear_pltc.checked,clearTripay:form.elements.clear_tripay.checked,provisioning:{eggId:Number(form.elements.egg_id?.value||0),locationId:Number(form.elements.location_id?.value||0),dockerImage:(form.elements.docker_image?.value||'').trim(),startup:(form.elements.startup?.value||'').trim()}};const mapped=[['plta','plta'],['pltc','pltc'],['tripay_merchant_code','tripayMerchantCode'],['tripay_api_key','tripayApiKey'],['tripay_private_key','tripayPrivateKey']];for(const[from,to]of mapped){const value=form.elements[from].value.trim();if(value)payload[to]=value}busy(button,true,'MENYIMPAN…');try{const data=await post('platform/panel/settings',payload);state.panelAutoOrder=data;form.elements.plta.value='';form.elements.pltc.value='';form.elements.tripay_merchant_code.value='';form.elements.tripay_api_key.value='';form.elements.tripay_private_key.value='';form.elements.clear_plta.checked=false;form.elements.clear_pltc.checked=false;form.elements.clear_tripay.checked=false;$('panelAutoOrderStatus').textContent=panelStatusText(data);toast('Konfigurasi Panel disimpan terenkripsi.')}catch(error){toast(error.message,true)}finally{busy(button,false)}}
