function panelPackageAction(event){const remove=event.target.closest('[data-panel-package-remove]');if(!remove)return;const cards=$('panelPackageEditor').querySelectorAll('[data-panel-package]');if(cards.length<=1)return toast('Minimal satu paket diperlukan.',true);remove.closest('[data-panel-package]').remove()}
async function savePanelProducts(event){event.preventDefault();const btn=event.currentTarget.querySelector('[type="submit"]');let products;try{products=JSON.parse($('panelProductsJson').value||'[]')}catch{return toast('JSON produk tidak valid.',true)}if(!Array.isArray(products))return toast('Katalog produk harus berupa array JSON.',true);busy(btn,true,'MENYIMPAN…');try{const data=await post('platform/panel/settings',{products});state.panelAutoOrder=data;renderPanelProductsSummary(data.products);toast('Katalog produk disimpan.')}catch(error){toast(error.message,true)}finally{busy(btn,false)}}
function renderPanelProductsSummary(products=[]){const el=$('panelProductsSummary');if(!el)return;el.innerHTML=(products||[]).length?products.map(p=>`<div class="list-item"><span><b>${escapeHtml(p.name)}</b><br><small>${escapeHtml(p.type)}${p.type==='premium'?` · ${escapeHtml(p.days)} hari`:` · stok ${escapeHtml(p.inStock??0)}`} · ${escapeHtml(p.id)}</small></span><div class="actions"><b>${formatIdr(p.price)}</b><span class="chip ${p.enabled?'user':''}">${p.enabled?'AKTIF':'NONAKTIF'}</span></div></div>`).join(''):'<p>Belum ada produk.</p>'}
function renderManualTopups(topups=[]){$('manualTopupRequests').innerHTML=topups.map(item=>`<div class="list-item"><span><b>${escapeHtml(formatIdr(item.amount))}</b><br><small>${escapeHtml(item.createdAt?new Date(item.createdAt).toLocaleString('id-ID'):'—')} · ${escapeHtml(item.merchantRef||item.id)}</small></span><div class="actions"><button class="mini" data-manual-topup="${escapeHtml(item.id)}" data-manual-decision="approve">SETUJUI</button><button class="mini danger" data-manual-topup="${escapeHtml(item.id)}" data-manual-decision="reject">TOLAK</button></div></div>`).join('')||'<p>Tidak ada permintaan top up yang menunggu verifikasi.</p>'}
async function loadManualTopups(){if(!hasRole('owner'))return;const data=await api('platform/panel/manual-topups');renderManualTopups(data.topups||[])}
async function manualTopupAction(event){const button=event.target.closest('[data-manual-topup]');if(!button)return;const decision=button.dataset.manualDecision,id=button.dataset.manualTopup;if(!confirm(`${decision==='approve'?'Setujui':'Tolak'} permintaan top up ini? Pastikan pembayaran DANA sudah diperiksa.`))return;busy(button,true);try{await post('platform/panel/manual-topups/review',{id,decision});toast(decision==='approve'?'Saldo pengguna berhasil ditambahkan.':'Permintaan top up ditolak.');await loadManualTopups()}catch(error){toast(error.message,true)}finally{busy(button,false)}}

function renderAudit(logs){$('auditList').innerHTML=logs.map(log=>{const feedback=log.action==='feedback.submit'&&log.metadata&&typeof log.metadata==='object'?`<br><small><b>${escapeHtml(log.metadata.title||'Feedback')}</b><br>${escapeHtml(log.metadata.description||'')}</small>`:'';return`<div class="list-item"><span><b>${escapeHtml(log.action)}</b> · ${escapeHtml(log.actor_email)}<br><small>${escapeHtml(log.target||'')}</small>${feedback}</span><time>${escapeHtml(new Date(log.created_at).toLocaleString('id-ID'))}</time></div>`}).join('')||'<p>Belum ada audit log.</p>'}
function filterOwner() {const q=$('ownerSearch').value.trim().toLowerCase();$('ownerTable').querySelectorAll('tr[data-search]').forEach(row=>row.classList.toggle('hidden',Boolean(q&&!row.dataset.search.includes(q))))}
async function ownerAction(event){const save=event.target.closest('[data-user-save]'),ban=event.target.closest('[data-user-ban]'),del=event.target.closest('[data-user-delete]');try{if(save){const select=document.querySelector(`[data-role-id="${CSS.escape(save.dataset.userSave)}"]`);await api(`platform/admin/users/${save.dataset.userSave}/roles`,{method:'PATCH',body:JSON.stringify({roles:[...select.selectedOptions].map(x=>x.value)})});toast('Role diperbarui.')}if(ban){await api(`platform/admin/users/${ban.dataset.userBan}/ban`,{method:'PATCH',body:JSON.stringify({banned:ban.dataset.banned!=='true'})});toast('Status diperbarui.')}if(del&&confirm('Hapus akun permanen?')){await api(`platform/admin/users/${del.dataset.userDelete}`,{method:'DELETE'});toast('Akun dihapus.')}if(save||ban||del)await loadOwner()}catch(error){toast(error.message,true)}}
async function createAccount(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button');busy(button,true,'MEMBUAT...');try{await post('platform/admin/users',{username:form.elements.username.value,email:form.elements.email.value,password:form.elements.password.value,roles:[...form.elements.roles.selectedOptions].map(x=>x.value)});form.reset();toast('Akun dibuat.');await loadOwner()}catch(error){toast(error.message,true)}finally{busy(button,false)}}
async function applyMedia(event){event.preventDefault();if(!state.selected)return toast('Pilih session dahulu.',true);const file=$('mediaFile').files[0],url=$('mediaUrl').value.trim(),kind=$('mediaKind').value,button=event.currentTarget.querySelector('button');if(!file&&!url)return toast('Masukkan URL atau file.',true);busy(button,true,'MENGUNGGAH...');$('mediaProgress').classList.remove('hidden');try{let payload={session_id:state.selected,kind,url};if(file){const max=file.type.startsWith('video/')?15*1024*1024:8*1024*1024;if(file.size>max)throw new Error(`File maksimal ${max/1024/1024} MB.`);const signed=await post('platform/media/sign',{session_id:state.selected,kind,mime_type:file.type});$('mediaProgress').textContent='Mengunggah file...';const{error}=await state.storage.storage.from('umi-media').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type,upsert:true});if(error)throw error;payload={session_id:state.selected,kind,storage_path:signed.path,mime_type:file.type,size_bytes:file.size}}$('mediaProgress').textContent='Menerapkan media...';await post('platform/media/apply',payload);$('mediaProgress').textContent='Media berhasil diterapkan.';$('mediaFile').value='';$('mediaUrl').value='';toast('Media bot diperbarui.')}catch(error){$('mediaProgress').textContent=error.message;toast(error.message,true)}finally{busy(button,false)}}
function appendAgentMessage(role,text){const box=$('agentMessages'),item=document.createElement('article');item.className=`message ${role==='user'?'mine':''}`;const p=document.createElement('p');p.textContent=String(text||'');item.append(p);box.append(item);box.scrollTop=box.scrollHeight}
async function loadAgent(){const owner=hasRole('owner'),data=await api(owner?'platform/agent/status':'agent/status');const status=$('agentStatus');status.textContent=data.configured?`SIAP · ${String(AGENT_PROVIDER_LABEL[data.provider]||data.provider||'gemini').toUpperCase()}`:'BUTUH API KEY';status.className=`chip ${data.configured?'partner':'owner'}`;$('agentIntro').textContent=owner?'Mode owner aktif: Agent dapat memantau bot dan memakai tool server yang dijaga policy. Untuk API key dan terminal, buka AI Owner.':'Agent bantuan untuk website dan Jadibot. Workspace publik dipisahkan dari server dan tidak memiliki akses shell.'}
async function sendAgent(event){event.preventDefault();const input=$('agentInput'),button=event.currentTarget.querySelector('button'),prompt=input.value.trim();if(!prompt)return;appendAgentMessage('user',prompt);input.value='';busy(button,true,'BERPIKIR…');try{const data=await post(hasRole('owner')?'platform/agent/chat':'agent/chat',{prompt});appendAgentMessage('assistant',data.answer||'Agent tidak mengirim jawaban.')}catch(error){appendAgentMessage('assistant',`Error: ${error.message}`)}finally{busy(button,false)}}
