async function testAgentConnection(){const button=$('testAgentConnection'),box=$('agentTestResult');if(!button||!hasRole('owner'))return;busy(button,true,'MENGUJI...');if(box){box.textContent='Memanggil provider AI aktif… (maksimal ±20 detik)';box.dataset.touched='1'}try{const data=await post('platform/agent/test',{});const label=AGENT_PROVIDER_LABEL[data?.provider]||data?.provider||'-';if(box)box.innerHTML=`<b>BERHASIL</b> · ${escapeHtml(label)} · ${escapeHtml(data?.model||'-')} · ${Number(data?.ms)||0} ms — jawaban model: “${escapeHtml(data?.reply||'')}”`;toast('Koneksi AI berhasil diuji.')}catch(error){const head=Number(error.status)===429?'KUOTA HABIS':'GAGAL';if(box)box.innerHTML=`<b>${head}</b> — ${escapeHtml(error.message)}`;toast(error.message,true)}finally{busy(button,false)}}
async function loadOwnerAgent(){const data=await api('platform/agent/status'),notice=$('ownerAgentStatus'),health=data.health||{},monitor=`Monitor · Bot utama: ${health.mainBotConnected?'online':'offline'} · Jadibot: ${Number(health.jadibotConnected)||0} online · Memori: ${Number(health.memoryMb)||0} MB`;notice.textContent=data.configured?`Agent siap · Provider: ${AGENT_PROVIDER_LABEL[data.provider]||data.provider||'Gemini'} · Model: ${data.model||AGENT_DEFAULT_MODEL[data.provider]||AGENT_DEFAULT_MODEL.gemini} · ${monitor}`:`AI belum dikonfigurasi. ${monitor}`;const form=$('agentSettingsForm'),provider=data.provider||'gemini';form.elements.provider.value=provider;form.elements.model.value=data.model||AGENT_DEFAULT_MODEL[provider]||AGENT_DEFAULT_MODEL.gemini;form.elements.model.placeholder=AGENT_DEFAULT_MODEL[provider]||AGENT_DEFAULT_MODEL.gemini;const testBox=$('agentTestResult');if(testBox&&!testBox.dataset.touched)testBox.textContent=`Provider aktif: ${AGENT_PROVIDER_LABEL[provider]||provider}. Tekan TES KONEKSI AI untuk memanggil model (${data.model||AGENT_DEFAULT_MODEL[provider]||'-'}).`}
async function loadProfile(){
  /* Pastikan profile terbaru dari server */
  try { await hydrateIdentity() } catch {}
  const u=state.profile||state.session?.user||{};
  const el=id=>document.getElementById(id);
  if(el('profileUsername'))el('profileUsername').value=u.username||u.user_metadata?.username||'—';
  if(el('profileEmail'))el('profileEmail').value=u.email||'—';
  if(el('profileRole'))el('profileRole').textContent=(u.roles||[u.role||'user']).join(', ')||'user';
  if(el('profileJoined'))el('profileJoined').textContent=u.created_at?new Date(u.created_at).toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'}):'—';
  /* Avatar / inisial */
  const avatarEl=el('profileAvatar');
  if(avatarEl){const name=u.username||u.email||'?';avatarEl.textContent=name.charAt(0).toUpperCase()}
  const dn=el('profileDisplayName');if(dn)dn.textContent=u.username||u.user_metadata?.username||u.email||'—';
  const dr=el('profileDisplayRole');if(dr)dr.textContent=(u.roles||[]).join(', ')||'user';
  /* Token */
  let apiToken=u.api_token||'';
  let tokenVisible=false;
  const tokenEl=el('profileToken'),toggleBtn=el('toggleTokenBtn'),copyBtn=el('copyTokenBtn'),regenBtn=el('regenerateTokenBtn');
  if(tokenEl)tokenEl.textContent=apiToken?'••••••••••••••••':'Belum ada token. Klik REGENERATE.';
  if(toggleBtn){toggleBtn.onclick=()=>{if(!apiToken)return toast('Belum ada token. Klik REGENERATE dahulu.',true);tokenVisible=!tokenVisible;if(tokenEl)tokenEl.textContent=tokenVisible?apiToken:'••••••••••••••••';toggleBtn.textContent=tokenVisible?'SEMBUNYIKAN':'TAMPILKAN'};}
  if(copyBtn){copyBtn.onclick=()=>{if(!apiToken)return toast('Belum ada token.',true);navigator.clipboard.writeText(apiToken).then(()=>toast('Token tersalin!')).catch(()=>toast('Gagal menyalin',true));};}
  if(regenBtn){regenBtn.onclick=async()=>{if(!confirm('Regenerate token? Token lama akan tidak berlaku.'))return;try{const d=await post('platform/auth/token');if(d.token){apiToken=d.token;if(state.profile)state.profile.api_token=d.token;tokenVisible=false;if(tokenEl)tokenEl.textContent='••••••••••••••••';if(toggleBtn)toggleBtn.textContent='TAMPILKAN';toast('Token baru dibuat!')}else toast(d.error||'Gagal',true)}catch(e){toast(e.message,true)}};}
  /* Password */
  const pwForm=el('changePasswordForm');
  if(pwForm&&!pwForm._bound){pwForm._bound=true;pwForm.onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;try{const d=await post('platform/auth/change-password',{old_password:f.elements.old_password.value,new_password:f.elements.new_password.value});if(d.ok){f.reset();toast('Password berhasil diubah!')}else toast(d.error||'Gagal',true)}catch(err){toast(err.message,true)}};}
}
