function rememberRoute(hash){try{if(hash&&/^#[a-z-]+$/.test(hash))localStorage.setItem('umi_return_to',hash)}catch{}}
function consumeRoute(fallback=''){try{const value=localStorage.getItem('umi_return_to')||'';localStorage.removeItem('umi_return_to');return /^#[a-z-]+$/.test(value)?value:fallback}catch{return fallback}}
function oauthFragment(){if(UMI_OAUTH_EARLY)return UMI_OAUTH_EARLY;/* Supabase mengirim token lewat fragment (#access_token=...). Fragment itu MENGGANTIKAN
   tujuan awal seperti #dashboard, jadi dibaca manual di sini lalu URL dibersihkan. */try{const raw=String(location.hash||'').replace(/^#/,'');if(!raw.includes('access_token=')&&!raw.includes('error_description='))return null;const params=new URLSearchParams(raw);if(params.get('error_description')||params.get('error'))return{error:params.get('error_description')||params.get('error')};const access=params.get('access_token');if(!access)return null;return{access_token:access,refresh_token:params.get('refresh_token')||'',expires_in:Number(params.get('expires_in'))||3600}}catch{return null}}
function clearOAuthFragment(fallback){try{if(!/access_token=|error_description=/.test(location.hash))return;const back=(()=>{try{const v=localStorage.getItem('umi_return_to')||'';localStorage.removeItem('umi_return_to');return /^#[a-z-]+$/.test(v)?v:''}catch{return ''}})();history.replaceState(null,'',(back||fallback||'#dashboard'))}catch{}}
function captureSupabaseSession(){const frag=oauthFragment();if(frag&&frag.access_token){saveSession({access_token:frag.access_token,refresh_token:frag.refresh_token,expires_in:frag.expires_in,user:null});return Promise.resolve({source:'fragment',session:frag})}try{const client=state.storage;if(!client?.auth)return Promise.resolve(null);return Promise.resolve(client.auth.getSession()).then(({data})=>{const session=data?.session;if(!session?.access_token)return null;saveSession({access_token:session.access_token,refresh_token:session.refresh_token,expires_in:session.expires_in||3600,user:session.user||null});if(session.user)applyIdentity(session.user);return session}).catch(()=>null)}catch{return Promise.resolve(null)}}
let premiumSearchTimer=null;
async function searchPremiumFeatures(query){
  const box=$('premiumFeatureResults');if(!box)return;
  const q=String(query||'').trim();
  if(q.length<2){box.innerHTML='<p class="muted">Ketik minimal 2 huruf untuk mencari fitur.</p>';return}
  const data=await api('premium/catalog?q='+encodeURIComponent(q)+'&limit=12');
  const features=data.features||[];
  box.innerHTML=features.length?features.map(f=>{
    const value=(f.commands&&f.commands[0])?f.commands[0]:f.key;
    const label=(f.commands&&f.commands[0])?('.'+f.commands[0]):(f.name||f.key);
    return `<button class="mini" type="button" data-premium-add="${escapeHtml(value)}">${escapeHtml(label)}<br><small>${escapeHtml(f.key)}</small></button>`;
  }).join(' '):'<p class="muted">Tidak ada fitur yang cocok.</p>';
}
function premiumSearchInput(){clearTimeout(premiumSearchTimer);const input=$('premiumFeatureQuery');if(!input)return;premiumSearchTimer=setTimeout(()=>searchPremiumFeatures(input.value).catch(error=>toast(error.message,true)),350)}
function premiumSearchClick(event){const button=event.target.closest('[data-premium-add]');if(!button)return;const form=$('settingsForm');const area=form&&form.elements.premium_plugins;if(!area)return;const value=button.dataset.premiumAdd;const lines=area.value.split(/\n/).map(x=>x.trim()).filter(Boolean);if(!lines.includes(value))lines.push(value);area.value=lines.join('\n');toast(value+' ditambahkan ke daftar. Jangan lupa SIMPAN.')}
function currentTheme(){return document.documentElement.getAttribute('data-theme')==='light'?'light':'dark'}
function applyTheme(theme,persist){
  const next=theme==='light'?'light':'dark';
  document.documentElement.setAttribute('data-theme',next);
  document.documentElement.style.colorScheme=next;
  const meta=document.querySelector('meta[name="theme-color"]');
  if(meta)meta.setAttribute('content',next==='light'?'#eef3fb':'#050d1f');
  const button=$('themeToggle');
  if(button){
    button.setAttribute('aria-pressed',String(next==='light'));
    button.title=next==='light'?'Tema terang aktif — klik untuk gelap':'Tema gelap aktif — klik untuk terang';
  }
  if(persist){try{localStorage.setItem('umi-theme',next)}catch{}}
}
function toggleNav(open){
  const nav=$('mainNav'),scrim=$('navScrim'),button=$('menuToggle');
  if(!nav)return;
  // Status ditentukan dari drawer DAN scrim: kalau salah satu masih terbuka,
  // tombol menu harus menutup semuanya (dulu scrim bisa tertinggal terbuka).
  const currentlyOpen=nav.classList.contains('open')||Boolean(scrim&&scrim.classList.contains('open'));
  const next=typeof open==='boolean'?open:!currentlyOpen;
  nav.classList.toggle('open',next);
  if(scrim){scrim.classList.toggle('open',next);scrim.hidden=!next}
  if(button)button.setAttribute('aria-expanded',String(next));
  document.body.classList.toggle('nav-open',next);
  if(next){const first=nav.querySelector('a,button');if(first)first.focus({preventScroll:true})}
}
function bindShell(){
  applyTheme(currentTheme(),false);
  const themeButton=$('themeToggle');
  if(themeButton)themeButton.onclick=()=>applyTheme(currentTheme()==='light'?'dark':'light',true);
  const menu=$('menuToggle');
  if(menu)menu.onclick=()=>toggleNav();
  const scrim=$('navScrim');
  if(scrim)scrim.onclick=()=>toggleNav(false);
  const closeNav=$('navClose');
  if(closeNav)closeNav.onclick=()=>toggleNav(false);
  const refreshLive=$('ownerLiveRefresh');
  if(refreshLive)refreshLive.onclick=()=>refreshOwnerStats(false);
  const refreshOwnerButton=$('refreshOwner');
  if(refreshOwnerButton)refreshOwnerButton.onclick=()=>loadOwner().catch(error=>toast(error.message,true));
  const refreshAuditButton=$('refreshAudit');
  if(refreshAuditButton)refreshAuditButton.onclick=()=>api('platform/audit').then(data=>renderAudit(data.logs||[])).catch(error=>toast(error.message,true));
  document.addEventListener('keydown',event=>{if(event.key==='Escape')toggleNav(false)});
}
